test("retired leave totals scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "cap", "2.00");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "0");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  expect(await ui.setSettingDated(pg_uma, "cap", "", "2026-03-05", "2.00")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50", "from": "2026-03-16", "to": "2026-03-12"})).toBe(false);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "4.00"}));
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "3.33"}));
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_cam_0, "settle")).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.delegate(pg_vic, {"user": "wes", "from": "2026-03-15", "to": "2026-03-20"})).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("0.50");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("4.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.50");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("0.50");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("SETTLED");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("4.00");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.50");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-due-total")).toHaveText("0.50");
  await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("0.00");
  const c_ben_0 = ui.must(await ui.quickAdd(pg_wes, {"name": "Ben", "amount": "3.33"}, p_ben));
  await ui.refresh(pg_vic);
  expect(await ui.claimAction(pg_vic, c_ada_0, "open")).toBe(true);
  expect(await ui.watch(pg_vic, p_cam, true)).toBe(true);
  expect(await ui.statement(pg_vic, p_ada)).toBe(true);
  expect(await ui.editClaim(pg_vic, c_ben_0, {"amount": "0.04"})).toBe(true);
  expect(await ui.claimAction(pg_vic, c_ben_0, "void")).toBe(true);
  expect(await ui.editPerson(pg_vic, p_ben, {"terms": "3"})).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("3.33");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.50");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("0.50");

