836- *  is not showing and the cell is no longer what it was (or the typed value, normalised, is a
837- *  value it could not have had before). */
838-async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
839-  for (const [k, v] of Object.entries(f)) {
840-    const cell = await shown(c.getByTestId(`claim-${k}`));
